const payload = $json.body ?? $json;
const alerts = (payload.alerts ?? []).slice(0, 10);
const status = String(payload.status ?? alerts[0]?.status ?? 'unknown').toLowerCase();
const summary = payload.commonAnnotations?.summary ?? alerts[0]?.annotations?.summary ?? 'Cinema alert received';
const descriptions = alerts.map((alert) => {
  const labels = alert.labels ?? {};
  const annotations = alert.annotations ?? {};
  return `• ${labels.alertname ?? 'Alert'} (${labels.severity ?? 'unknown'}): ${annotations.summary ?? summary}${labels.instance ? ` [${labels.instance}]` : ''}`;
}).join('\n');
const version = payload.commonLabels?.version ?? alerts.find((alert) => alert.labels?.version)?.labels?.version ?? '';
const rootText = `${status === 'resolved' ? '✅' : '🚨'} *Cinema ${status === 'resolved' ? '장애 해소' : '장애 알림'}*\n${descriptions || summary}\n
지문: ${alerts.map((alert) => alert.fingerprint).filter(Boolean).join(', ') || '없음'}`.slice(0, 3500);
return [{ json: { status, summary, version, rootText, alerts, startedAt: alerts[0]?.startsAt ?? new Date().toISOString() } }];

const alert = $('Normalize Alert').first().json;
const loki = $('Loki Error Logs').first().json;
const results = loki.data?.result ?? loki.body?.data?.result ?? [];
const lines = results.flatMap((stream) => stream.values ?? []).map((entry) => entry[1]).slice(0, 25);
const shaFromLogs = lines.join('\n').match(/\bversion=([a-f0-9]{40})\b/i)?.[1] ?? '';
const version = /^[a-f0-9]{40}$/i.test(alert.version) ? alert.version : shaFromLogs;
const frame = lines.join('\n').match(/at\s+([\w.$]+)\([^()]*\.java:(\d+)\)/);
const className = frame?.[1]?.split('$')[0]?.replace(/\.[^.]+$/, '') ?? '';
const lineNumber = frame ? Number(frame[2]) : 0;
const sourcePath = className.startsWith('com.example.') ? `src/main/java/${className.replaceAll('.', '/')}.java` : '';
const sourceUrl = version && sourcePath ? `https://raw.githubusercontent.com/strangehoon/cinema/${version}/${sourcePath}` : '';
const redact = (value) => String(value ?? '')
  .replace(/(authorization|password|token|secret|api[_-]?key|payment[_-]?key|user[_-]?id|customer[_-]?id|member[_-]?id|order[_-]?id)\s*[:=]\s*[^\s,;]+/gi, '$1=[REDACTED]')
  .replace(/\bBearer\s+[^\s,;]+/gi, 'Bearer [REDACTED]')
  .replace(/\b[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g, '[EMAIL]')
  .replace(/\b\d{2,3}-\d{3,4}-\d{4}\b/g, '[PHONE]')
  .replace(/\b(?:sk-[A-Za-z0-9_-]{20,}|xox[baprs]-[A-Za-z0-9-]+|eyJ[A-Za-z0-9_-]{20,})\b/g, '[TOKEN]');
const metrics = $('Prometheus Error Metrics').first().json;
const metricRows = metrics.data?.result ?? metrics.body?.data?.result ?? [];
return [{ json: { version, sourceUrl, lineNumber, logs: redact(lines.join('\n').slice(0, 12000)), metrics: redact(JSON.stringify(metricRows).slice(0, 4000)), alertStatus: alert.status, summary: redact(alert.summary) } }];

const context = $('Select Exact Deployment Context').first().json;
const response = $('Read Deployed Source').first().json;
let source = typeof response === 'string' ? response : (response.data ?? response.body ?? '');
if (typeof source !== 'string') source = JSON.stringify(source);
const sourceLines = source.split('
');
let code = '';
if (context.lineNumber > 0 && sourceLines.length > 1) {
  const from = Math.max(0, context.lineNumber - 41);
  const to = Math.min(sourceLines.length, context.lineNumber + 40);
  code = sourceLines.slice(from, to).map((line, index) => `${from + index + 1}: ${line}`).join('
').slice(0, 8000);
}
const codeContext = context.sourceUrl && code ? `Exact deployment source (${context.version}, ${context.sourceUrl}):
${code}` : `Exact deployment source is unavailable. version=${context.version || 'unknown'}, source=${context.sourceUrl || 'no Java stack frame found'}. Do not infer code details.`;
const prompt = `장애 알림: ${context.summary} (상태: ${context.alertStatus})
배포 SHA: ${context.version || '로그에서 확인 불가'}

최근 15분 ERROR 로그(민감정보 마스킹 후):
${context.logs || 'ERROR 로그가 조회되지 않았습니다.'}

현재 API 5xx 지표 요약:
${context.metrics || '지표를 조회할 수 없습니다.'}

${codeContext}

한국어로 간결하게 답하세요. 1) 가능성이 높은 원인 후보를 근거와 함께 최대 3개, 2) 근거가 부족하면 불확실성을 명시, 3) 운영자가 다음으로 확인할 항목을 순서대로 제시하세요. 코드 변경이나 자동 복구를 지시하지 말고, 자동 조치는 수행하지 않았다고 밝혀주세요.`;
return [{ json: { prompt } }];

const result = $('OpenAI Incident Analysis').first().json;
const root = $('Slack Root Alert').first().json;
const text = result.output_text ?? result.output?.flatMap((item) => item.content ?? []).find((part) => part.type === 'output_text')?.text;
const analysis = text || 'AI 분석 호출에 실패했습니다. 최초 Slack 장애 알림과 로그·지표는 유지되며, OpenAI 자격 증명과 n8n 실행 로그를 확인해 주세요.';
const prefix = text ? '*AI 원인 후보 (참고용)*' : '*AI 분석 실패*';
return [{ json: { channel: root.channel, thread_ts: root.ts, text: `${prefix}\n${analysis}`.slice(0, 12000) } }];
